arguments.command:
mkdir -p src test && cat > src/checkout.mjs <<'E'
// Provisional policy, pending product decision: reject orders with expired promotions.
export class ExpiredPromotionError extends Error {
  constructor(code) {
    super(`Promotion ${code} has expired`);
    this.name = 'ExpiredPromotionError';
    this.code = 'EXPIRED_PROMOTION';
    this.promotionCode = code;
  }
}

export function checkout({ items, promotion }, now = new Date()) {
  const subtotal = items.reduce((s, i) => s + i.price * i.quantity, 0);
  let discount = 0;
  if (promotion) {
    if (now > new Date(promotion.expiresAt)) throw new ExpiredPromotionError(promotion.code);
    discount = Math.round(subtotal * promotion.percentOff) / 100;
  }
  return { subtotal, discount, total: subtotal - discount };
}
E
cat > test/checkout.test.mjs <<'E'
import test from 'node:test';
import assert from 'node:assert/strict';
import { checkout, ExpiredPromotionError } from '../src/checkout.mjs';

const items = [{ price: 50, quantity: 2 }];
const now = new Date('2026-11-21T12:00:00Z');
const promo = (expiresAt) => ({ code: 'SAVE10', percentOff: 10, expiresAt });

test('valid promotion applies discount', () => {
  assert.deepEqual(checkout({ items, promotion: promo('2026-12-01T00:00:00Z') }, now),
    { subtotal: 100, discount: 10, total: 90 });
});
test('no promotion charges full price', () => {
  assert.equal(checkout({ items }, now).total, 100);
});
test('expired promotion rejects order', () => {
  assert.throws(() => checkout({ items, promotion: promo('2026-11-01T00:00:00Z') }, now),
    (e) => e instanceof ExpiredPromotionError && e.code === 'EXPIRED_PROMOTION' && e.promotionCode === 'SAVE10');
});
test('promotion expiring exactly now is still valid', () => {
  assert.equal(checkout({ items, promotion: promo(now.toISOString()) }, now).total, 90);
});
E
node --test 2>&1 | tail -8

